add('two','inr','inertia',3,'№9',['I0'],r=>{const m=pick(r,[0.1,0.2,0.5]),L=pick(r,[0.4,0.6,1]),I=9*m*L*L/4;
return[`Два шара массами m = ${F(m)} кг и 2m закреплены на невесомом стержне длиной ${F(L)} м: шар m — на середине, шар 2m — на конце. Найдите момент инерции системы относительно оси, перпендикулярной стержню и проходящей через его свободный конец. Размерами шаров пренебречь.`,`m = ${F(m)} кг; L = ${F(L)} м`,[`Момент инерции аддитивен: I = Σmᵢrᵢ² (точки).`,`Шар m — на расстоянии L/2 от оси: m(L/2)² = mL²/4. Шар 2m — на расстоянии L: 2m·L² = 2mL².`,`I = mL²/4 + 2mL² = 9mL²/4 = 2,25·${F(m)}·${F(L)}² = ${F(I)} кг·м².`],I,'кг·м²',[[2*m*L*L,'Забыт шар m на середине стержня','f'],[m*L*L/4+2*m*L*L/4,'Шар 2m на расстоянии L, а не L/2','f']]];});
add('sph','inr','inertia',3,'№10',['Itab','st'],r=>{const m=pick(r,[1,2,5]),R=pick(r,[0.1,0.2,0.3]),I=13*m*R*R/20;
return[`Определите момент инерции шара радиусом ${F(R)} м и массой ${m} кг относительно оси, проходящей через середину радиуса.`,`m = ${m} кг; R = ${F(R)} м`,[`Ось на расстоянии d = R/2 от центра: I_c = 2mR²/5.`,`Штейнер: I = 2mR²/5 + m(R/2)² = (2/5 + 1/4)mR² = 13mR²/20.`,`I = 0,65·${m}·${F(R)}² = ${F(I)} кг·м².`],I,'кг·м²',[[2*m*R*R/5,'Это I_c; добавьте m(R/2)² (Штейнер)','f'],[7*m*R*R/5,'Расстояние между осями R/2, а не R','f']]];});

