add('mk3','mkt','mkt_gas',2,'Савельев §98 (газовые законы)',['g_iso'],r=>{const p1=pick(r,[100,150,200]),t1=pick(r,[27,7,-3]),t2=pick(r,[127,177,227]),T1=t1+273,T2=t2+273,p2=p1*T2/T1;
return[`Газ в закрытом сосуде при ${t1} °C имеет давление ${p1} кПа. Каким станет давление при нагревании до ${t2} °C?`,`p₁ = ${p1} кПа; t₁ = ${t1} °C; t₂ = ${t2} °C; V = const`,[`В кельвинах: T₁ = ${T1} К, T₂ = ${T2} К.`,'При V = const p/T = const, откуда p₂ = p₁T₂/T₁.',`p₂ = ${p1}·${T2}/${T1} ≈ ${F(p2)} кПа.`],p2,'кПа',[[p1*T1/T2,'Отношение температур перевёрнуто','f'],[p1*(T2-T1)/T1,'Найдено относительное изменение, а не новое давление','f']]];});
add('th1','thd','thd_proc',1,'Савельев §§96, 105',['g_A'],r=>{const n=pick(r,[1,2,3,4]),dT=pick(r,[20,50,100]),A=n*RG*dT;
return[`${n} моль идеального газа нагрели при постоянном давлении на ${dT} К. Найдите работу газа.`,`ν = ${n} моль; ΔT = ${dT} К; p = const`,['При p = const A = pΔV.','Из уравнения состояния pΔV = νRΔT.',`A = ${n}·8,31·${dT} ≈ ${F(A)} Дж.`],A,'Дж',[[1.5*A,'Это изменение внутренней энергии одноатомного газа, а не работа','f'],[n*dT,'Пропущена газовая постоянная R','f']]];});
add('th2','thd','thd_proc',2,'Савельев §§95, 102',['g_first','g_U'],r=>{const n=pick(r,[2,3,5]),dT=pick(r,[20,40,60]),Q=1.5*n*RG*dT;
return[`Одноатомный идеальный газ (${n} моль) нагревают при постоянном объёме на ${dT} К. Какое количество теплоты необходимо сообщить газу?`,`ν = ${n} моль; ΔT = ${dT} К; V = const; i = 3`,['При V = const работа A = 0, поэтому Q = ΔU.','ΔU = (i/2)νRΔT, для одноатомного газа i = 3.',`Q = 1,5·${n}·8,31·${dT} ≈ ${F(Q)} Дж.`],Q,'Дж',[[2.5*n*RG*dT,'Взята C_p; при V = const нужна C_V = 3R/2','f'],[n*RG*dT,'Это работа в изобарном процессе; здесь A = 0 и Q = ΔU','f']]];});
add('th3','thd','thd_proc',3,'Савельев §§103–104',['g_adi','g_U'],r=>{const n=pick(r,[1,2,4]),T1=pick(r,[500,600,700]),T2=pick(r,[300,350,400]),A=1.5*n*RG*(T1-T2);
return[`Одноатомный идеальный газ (${n} моль) адиабатно расширяется, температура падает с ${T1} К до ${T2} К. Найдите работу газа.`,`ν = ${n} моль; T₁ = ${T1} К; T₂ = ${T2} К; Q = 0`,['Адиабатный процесс: Q = 0, поэтому A = −ΔU.','ΔU = (3/2)νR(T₂ − T₁), значит A = (3/2)νR(T₁ − T₂).',`A = 1,5·${n}·8,31·(${T1} − ${T2}) ≈ ${F(A)} Дж.`],A,'Дж',[[-A,'Знак: при расширении работа газа положительна (A = −ΔU)','f'],[n*RG*(T1-T2),'Для одноатомного газа ΔU = (3/2)νRΔT, а не νRΔT','f']]];});
add('th4','thd','thd_proc',3,'Савельев §105',['g_A','g_first'],r=>{const n=pick(r,[1,2]),T=pick(r,[300,400,500]),k=pick(r,[2,3,5]),A=n*RG*T*Math.log(k);
return[`${n} моль идеального газа изотермически расширяются при температуре ${T} К, объём увеличивается в ${k} раза. Найдите работу газа.`,`ν = ${n} моль; T = ${T} К; V₂/V₁ = ${k}`,['При T = const A = ∫p dV = νRT·ln(V₂/V₁).',`A = ${n}·8,31·${T}·ln ${k} ≈ ${F(A)} Дж.`],A,'Дж',[[n*RG*T*(k-1),'Работа изотермного процесса содержит логарифм отношения объёмов, а не разность','f'],[n*RG*T,'Пропущен множитель ln(V₂/V₁)','f']]];});
add('en1','ent','ent_cyc',1,'Савельев §125',['g_eta'],r=>{const Q1=pick(r,[800,1000,1200]),q=pick(r,[0.6,0.7,0.75,0.8]),Q2=Math.round(Q1*q),e=(Q1-Q2)/Q1*100;
return[`Тепловая машина за цикл получает от нагревателя ${Q1} Дж и отдаёт холодильнику ${Q2} Дж. Найдите КПД машины в процентах.`,`Q₁ = ${Q1} Дж; Q₂′ = ${Q2} Дж`,['Работа за цикл A = Q₁ − Q₂′.','КПД η = A/Q₁.',`η = (${Q1} − ${Q2})/${Q1} ≈ ${F(e)} %.`],e,'%',[[Q2/Q1*100,'Это доля отданной теплоты, а не КПД','f'],[(Q1-Q2)/Q2*100,'Делить нужно на Q₁ (полученное тепло)','f']]];});
add('en2','ent','ent_cyc',2,'Савельев §§127, 129',['g_carnot'],r=>{const t1=pick(r,[227,377,527]),t2=pick(r,[27,47,67]),T1=t1+273,T2=t2+273,e=(1-T2/T1)*100;
return[`Идеальная тепловая машина работает по циклу Карно: температура нагревателя ${t1} °C, холодильника ${t2} °C. Найдите КПД машины в процентах.`,`t₁ = ${t1} °C; t₂ = ${t2} °C`,[`Переведём в кельвины: T₁ = ${T1} К, T₂ = ${T2} К.`,'КПД цикла Карно η = 1 − T₂/T₁.',`η = 1 − ${T2}/${T1} ≈ ${F(e)} %.`],e,'%',[[(1-t2/t1)*100,'Температуры нужно переводить в кельвины','u'],[T2/T1*100,'Это отношение температур; КПД η = 1 − T₂/T₁','f']]];});
add('en3','ent','ent_cyc',2,'Савельев §§125, 127',['g_carnot','g_eta'],r=>{const Q1=pick(r,[10,20,50]),T1=pick(r,[500,650,800]),T2=pick(r,[300,320]),A=Q1*(1-T2/T1);
return[`Идеальная машина Карно получает от нагревателя ${Q1} кДж теплоты за цикл. Температуры нагревателя и холодильника ${T1} К и ${T2} К. Найдите работу за цикл.`,`Q₁ = ${Q1} кДж; T₁ = ${T1} К; T₂ = ${T2} К`,['КПД цикла Карно η = 1 − T₂/T₁.','Работа A = ηQ₁.',`A = ${Q1}·(1 − ${T2}/${T1}) ≈ ${F(A)} кДж.`],A,'кДж',[[Q1*T2/T1,'Это теплота, отданная холодильнику, а не работа','f'],[Q1*(T1-T2)/T2,'КПД считают делением на T₁, а не на T₂','f']]];});
add('en4','ent','ent_cyc',3,'Савельев §132',['g_S'],r=>{const Q=pick(r,[600,900,1200]),tc=pick(r,[27,127,227]),T=tc+273,dS=Q/T;
return[`При изотермном обратимом расширении газ получил ${Q} Дж теплоты при температуре ${tc} °C. Найдите изменение энтропии газа.`,`Q = ${Q} Дж; t = ${tc} °C`,[`Температура в кельвинах: T = ${tc} + 273 = ${T} К.`,'При изотермном обратимом процессе ΔS = Q/T.',`ΔS = ${Q}/${T} ≈ ${F(dS)} Дж/К.`],dS,'Дж/К',[[Q/tc,'Температуру нужно брать в кельвинах','u'],[Q*T,'Энтропия — это Q/T, а не произведение','f']]];});
